import{_ as t,c as a,o,b0 as s}from"./chunks/framework.Dmsv_Tiv.js";const r="/media-docs/assets/7eb645a161768db0573b8d8c4f63bdfb.CVVAcrTQ.png",p="/media-docs/assets/027c41f5f8ca3d9bd9d2111e9ef42e64.CJnj9VGC.jpg",l="/media-docs/assets/4081cb62214939fc0373793eae0abbe1.CF5yadk4.jpg",d="/media-docs/assets/5e154cd7319212970de004ba7b2e6961.B0ouwIHH.jpg",g=JSON.parse('{"title":"LV005-视频开发","description":null,"frontmatter":{"title":"LV005-视频开发","date":"2025-11-20T10:22:00.000Z","icon":"famicons:logo-markdown","permalink":"/sdoc/vcodec/intro/126b14d1eb380373c8f5f3bf","index":true,"tags":null,"categories":null,"copyright":false,"keywords":null,"cover":null,"comments":null,"mathjax":null,"top":null,"description":null,"tdoc":{"detailDate":"2025-11-20T10:22:00.055Z","fulluuid":"3c8f5f3bfef14f78801bf52c040dea0c","useduuid":"3c8f5f3bf"}},"headers":[],"relativePath":"sdoc/vcodec/intro/126b14d1eb380373c8f5f3bf.md","filePath":"sdoc/20-视频编解码/01-概述/LV005-视频开发.md","lastUpdated":1767537778000}'),n={name:"sdoc/vcodec/intro/126b14d1eb380373c8f5f3bf.md"};function i(c,e,f,m,_,u){return o(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="lv005-视频开发" tabindex="-1">LV005-视频开发 <a class="header-anchor" href="#lv005-视频开发" aria-label="Permalink to &quot;LV005-视频开发&quot;">​</a></h1><p>前端时间看了极客时间的视频编解码相关的一个专栏，这里这个其实就是开场第一篇文档：为什么说视频开发是程序员的一片蓝海。</p><p>现在从事安防行业，对基本的视频编解码需要有一定的知识积累，偶然发现极客时间中有这么一些课程，但是并非免费，59大洋，但是为知识付费嘛，学到东西就很值。其实这些都是<strong>直接复制的文章的</strong>，主要是为了方便查看吧，而且自己这边做一遍笔记也印象更深刻，<strong>不做商业用途，仅限个人查阅学习使用</strong>。</p><h2 id="一、为什么要学音视频开发" tabindex="-1">一、为什么要学音视频开发？ <a class="header-anchor" href="#一、为什么要学音视频开发" aria-label="Permalink to &quot;一、为什么要学音视频开发？&quot;">​</a></h2><p>你好，我是李江，欢迎你跟我一起走进视频和图像的世界。从今天开始，我要用 15 节课的时间，和你分享视频中的那些核心技术。</p><p>那说起视频，随着以抖音和快手为代表的短视频平台火爆全球，市场对于视频研发人才的需求越来越旺盛。当然还有像随之而来的直播带货、疫情背景下视频会议产品的更新与迭代等等，都给工程师们创造了很多新的机会。</p><p>最简单粗暴的方式是，你可以直接通过各种招聘平台去了解相关的就业形势。就拿 Android 开发为例吧，现阶段做音视频开发的薪资水平，至少比同资历的 Android 开发高出 30% 左右。</p><img src="'+r+'" alt="img" style="zoom:50%;"><p>当然，除了实打实的物质回馈，我想更大的学习动力还是一些新技术、新应用，毕竟好奇是人类的天性，也是技术人进阶的驱动力。</p><p>拿我来说吧，我目前是在声网 Agora 担任视频专家，主要从事视频编码和传输方面的工作。但在此之前，我已经积累了 8 年之久，做过很多新的尝试和探索，收获颇丰。</p><p>早在 2013 年我还在浙大读硕士的时候，我就开始了视频编码与传输方向的研究。之后一步步转向视频编码的应用、传输策略的优化；再到高阶的视频网络传输、带宽预测、抗丢包等网络对抗技术；再后来就是人脸识别、表情识别和人流量检测等各种有意思的视频 AI 算法的落地。</p><p>总结来说，视频领域的方方面面，从底层原理到上层应用，我都有过深度参与和系统性的沉淀。这也是我开这门课的一个原动力，那就是希望能做更多的分享与输出，把这一路上踩的坑、体验到的技术痛点与乐趣与你分享，让更多有兴趣了解、转型视频开发的同学可以快速涉猎视频技术，而音视频工程师或者相关应用的产品经理也可以借此夯实视频基础、优化视频产品设计体验。</p><h2 id="二、学习视频技术究竟难在哪" tabindex="-1">二、学习视频技术究竟难在哪？ <a class="header-anchor" href="#二、学习视频技术究竟难在哪" aria-label="Permalink to &quot;二、学习视频技术究竟难在哪？&quot;">​</a></h2><p>在我看来，现在就是视频技术最好的时代。一方面，如你所见，当下即是刚需，视频技术的应用已经成为互联网平台的标配；另一方面，未来即是星辰大海，随着 AI、元宇宙等技术的发展，视频技术还有无限的想象空间。</p><p>但既然我们前面已经提到了技术痛点这个关键词，那学习门槛还是有的。就比如：</p><ul><li>抖音和快手的短视频需要应用图像处理和视频编码技术，如何在保持高画质的情况下，尽量减少视频文件的大小，是很难也很重要的；</li><li>连麦直播则需要懂 RTC 和直播技术，如何能够保证在各种网络状况下实现超低延时、降低卡顿率是一个非常难的问题；</li><li>视频会议则需要你十分熟悉 RTC 和转码合流服务等技术，几十上百人的大型视频会议，如何保证流畅度、卡顿率、画质等指标也是十分具有挑战性的。</li></ul><p>尤其对于一些视频技术小白来说，可能看公式都是有难度的。就比如说下面这个公式：</p><img src="'+p+'" alt="img" style="zoom:50%;"><p>这其实是一个二维 DCT 变换公式，是用来将图片从空域转到频域的。对于有些基础的同学来说，可能一眼就能看个大概。但是对于之前没有接触过视频编码的同学来说，可能要先从每个字母代表什么学起，然后才能再去搞清楚公式背后的计算逻辑。</p><p>有门槛只是一方面，我认为，视频技术难上手的另一个重要原因就是它涉及的技术太多了，这是事实。比如说视频前处理，就涉及到很多信号处理和 AI 技术；视频的编码算法，则会涉及到信息论和数学；而视频的传输就更多了，包含了各种网络协议和拥塞控制算法。你可以通过以下这张知识图谱去梳理其中的技术环节，既是构建知识网络，也可以查漏补缺。</p><img src="'+l+'" alt="img" style="zoom:25%;"><p>另外，也正是因为这点，目前市面上系统讲解视频的书籍和课程也是比较少的。同时，它与火热的音频技术相比，发展时间更短，所以沉淀下来的资料也不多。</p><h2 id="三、要学什么" tabindex="-1">三、要学什么？ <a class="header-anchor" href="#三、要学什么" aria-label="Permalink to &quot;三、要学什么？&quot;">​</a></h2><p>清楚了门槛，后面我们要解决的就是怎么迈过去，推开视频技术这扇大门了。</p><p>我联想到以前在公司内部做技术分享的场景，复盘问题其实是一种很好的学习方式。所以在设计课程的时候，我就假想同过去的自己对话。回想那些我曾经困惑的技术点和理论，以及难以解决的工程问题，希望能把那些广杂艰深、让初学者望而生畏的核心技术交付给你。</p><p>那么这门课程的具体内容是怎样的呢？我会从视频处理的全链路展开，具体分为图像基础和前处理、视频编码、视频传输和网络对抗、视频封装和播放四个模块。</p><img src="'+d+'" alt="img" style="zoom:50%;"><p><strong>图像基础和前处理</strong>：从视频和图像的基本概念讲起，陆续延伸到视频的颜色空间，尤其是 YUV 颜色空间，这是视频技术中非常重要的基础知识，同时也是很多视频工程师的学习难点。之后会讨论工程上常用的图像缩放算法及其原理。打好基础，后面事半功倍。</p><p><strong>视频编码</strong>：主要讲解在视频技术中占据重要地位的视频编码技术，重点学习编码算法的底层原理和具体算法的实现，让我们在使用编解码器的同时，也能更深一层，洞察其工作原理。另外，H264 码流是视频开发中必学的，所以我也会在这里和你讨论它的结构以及相关工程问题。深入原理，才能快速实践。</p><p><strong>视频传输和网络对抗</strong>：以实践为主，讲解具体的视频传输和弱网对抗技术，主要包括如何打包视频、预测网络带宽，以及如何在有限的带宽情况下控制好编码器的码率和发送包的速度。之后，我会手把手带你解决两个代表性的视频 Bug“花屏和卡顿”，并介绍一下视频会议中的常用技术 SVC。</p><p><strong>视频封装和播放</strong>：介绍常用的视频封装技术，并解决视频工程难题：音视频同步。</p><p>以上就是我要给你分享的重点内容，从最核心的原理、最新的应用到最常见的问题，我相信这门课能帮助你轻松跨入视频技术的大门。最后，我想说，技术赋能、常变常新，希望我们都能在时代的洪流中锚定目标与方向。</p>',32)])])}const h=t(n,[["render",i]]);export{g as __pageData,h as default};
